#[test]
fn replay_parity_rejects_mixed_parked_and_discarded_clocks_on_both_paths() {
    let origin_a = Ydoc::wire();
    let dependency = origin_a.plaintext_insert(0, "a");
    let origin_b = Ydoc::wire();
    origin_b.apply(&dependency).expect("seed dependent peer");
    let dependent = origin_b.plaintext_insert(1, "b");
    let overlap = decode_hex(OVERLAP_U2_HEX);
    let mixed = dohc_engine_collab::merge_updates(&[overlap, dependent])
        .expect("merge discarded and missing-dependency blocks");
    let mixed_sha = dohc_engine_collab::hex_sha256(&mixed);

    let (mut local, local_key) = setup_parity_store("mixed-parity-local", Regime::LocalOnly);
    let overlap_base = decode_hex(OVERLAP_U1_HEX);
    record_local_update(
        &mut local.store,
        &local_key,
        &overlap_base,
        &NoFaults,
        1_001,
    )
    .expect("overlap base");
    let local_error = record_local_update(&mut local.store, &local_key, &mixed, &NoFaults, 1_002)
        .expect_err("mixed local candidate must fail closed");
    assert!(matches!(
        local_error,
        CollabError::ReplayParityViolation { .. }
    ));
    assert_eq!(count(&local.store, "ydoc_updates", &local_key), 1);
    assert!(
        local
            .store
            .get_binary_blob(&mixed_sha)
            .expect("local blob lookup")
            .is_none(),
        "rejected mixed candidate must not reach the local blob store"
    );

    let (mut remote, remote_key) = setup_parity_store("mixed-parity-remote", Regime::Replicated);
    apply_remote_update(
        &mut remote.store,
        &remote_key,
        &RemoteUpdate {
            origin_id: "peer-overlap".to_owned(),
            origin_seq: 1,
            bytes: overlap_base,
        },
        &NoFaults,
        1_001,
    )
    .expect("remote overlap base");
    let remote_error = apply_remote_update(
        &mut remote.store,
        &remote_key,
        &RemoteUpdate {
            origin_id: "peer-mixed".to_owned(),
            origin_seq: 1,
            bytes: mixed,
        },
        &NoFaults,
        1_002,
    )
    .expect_err("mixed remote candidate must fail closed");
    assert!(matches!(
        remote_error,
        CollabError::ReplayParityViolation { .. }
    ));
    assert_eq!(count(&remote.store, "ydoc_updates", &remote_key), 1);
    assert!(
        remote
            .store
            .get_binary_blob(&mixed_sha)
            .expect("remote blob lookup")
            .is_none(),
        "rejected mixed candidate must not reach the remote blob store"
    );
}

#[test]
fn replay_parity_accepts_clean_resend_and_sequential_append() {
    let (mut ts, key) = setup_parity_store("valid-resend-append", Regime::LocalOnly);
    let producer = Ydoc::wire();
    let first = producer.plaintext_insert(0, "a");
    let first_outcome =
        record_local_update(&mut ts.store, &key, &first, &NoFaults, 1_001).expect("first insert");
    assert!(matches!(
        first_outcome,
        TxnOutcome::Committed(ref append) if !append.deduped
    ));

    let resend = record_local_update(&mut ts.store, &key, &first, &NoFaults, 1_002)
        .expect("clean-boundary resend");
    assert!(matches!(
        resend,
        TxnOutcome::Committed(ref append) if append.deduped
    ));

    let second = producer.plaintext_insert(1, "b");
    let append = record_local_update(&mut ts.store, &key, &second, &NoFaults, 1_003)
        .expect("sequential append");
    assert!(matches!(
        append,
        TxnOutcome::Committed(ref append) if !append.deduped
    ));
    assert_eq!(count(&ts.store, "ydoc_updates", &key), 2);
    let persisted = load_persisted(&ts.store, &key)
        .expect("load")
        .expect("marker");
    assert_eq!(persisted.doc.plaintext_string(), "ab");
}

#[test]
fn replay_parity_accepts_skip_gap_merge_when_gap_is_present() {
    let (mut ts, key) = setup_parity_store("valid-skip-gap", Regime::LocalOnly);
    let producer = Ydoc::wire();
    let first = producer.plaintext_insert(0, "a");
    let gap = producer.plaintext_insert(1, "b");
    let last = producer.plaintext_insert(2, "c");
    record_local_update(&mut ts.store, &key, &first, &NoFaults, 1_001).expect("first");
    record_local_update(&mut ts.store, &key, &gap, &NoFaults, 1_002).expect("gap dependency");

    let skip_gap = dohc_engine_collab::merge_updates(&[first, last]).expect("skip-gap merge");
    let outcome = record_local_update(&mut ts.store, &key, &skip_gap, &NoFaults, 1_003)
        .expect("skip-gap update with an integrated gap must be accepted");
    assert!(matches!(
        outcome,
        TxnOutcome::Committed(ref append) if !append.deduped
    ));
    assert_eq!(count(&ts.store, "ydoc_updates", &key), 3);
    let persisted = load_persisted(&ts.store, &key)
        .expect("load")
        .expect("marker");
    assert_eq!(persisted.doc.plaintext_string(), "abc");
}

#[test]
fn replay_parity_parks_cross_origin_missing_dependency_then_converges() {
    let (mut ts, key) = setup_parity_store("missing-dependency", Regime::Replicated);
    let origin_a = Ydoc::wire();
    let dependency = origin_a.plaintext_insert(0, "a");
    let origin_b = Ydoc::wire();
    origin_b.apply(&dependency).expect("seed dependent peer");
    let dependent = origin_b.plaintext_insert(1, "b");

    let parked = apply_remote_update(
        &mut ts.store,
        &key,
        &RemoteUpdate {
            origin_id: "origin-b".to_owned(),
            origin_seq: 1,
            bytes: dependent,
        },
        &NoFaults,
        1_001,
    )
    .expect("missing cross-origin dependency must be parked");
    assert!(matches!(
        parked,
        TxnOutcome::Committed(ReplicationApplyOutcome::Applied { .. })
    ));
    assert_eq!(count(&ts.store, "ydoc_updates", &key), 1);

    let resolved = apply_remote_update(
        &mut ts.store,
        &key,
        &RemoteUpdate {
            origin_id: "origin-a".to_owned(),
            origin_seq: 1,
            bytes: dependency,
        },
        &NoFaults,
        1_002,
    )
    .expect("dependency arrival must resolve the parked update");
    assert!(matches!(
        resolved,
        TxnOutcome::Committed(ReplicationApplyOutcome::Applied { .. })
    ));
    assert_eq!(count(&ts.store, "ydoc_updates", &key), 2);
    let persisted = load_persisted(&ts.store, &key)
        .expect("load")
        .expect("marker");
    assert_eq!(persisted.doc.plaintext_string(), "ab");
}

#[test]
fn compaction_preserves_parked_updates_until_dependency_arrives() {
    let (mut ts, key) = setup_parity_store("parked-compaction", Regime::Replicated);
    let origin_a = Ydoc::wire();
    let dependency = origin_a.plaintext_insert(0, "a");
    let origin_b = Ydoc::wire();
    origin_b.apply(&dependency).expect("seed dependent peer");
    let dependent = origin_b.plaintext_insert(1, "b");

    apply_remote_update(
        &mut ts.store,
        &key,
        &RemoteUpdate {
            origin_id: "origin-b".to_owned(),
            origin_seq: 1,
            bytes: dependent,
        },
        &NoFaults,
        1_001,
    )
    .expect("missing dependency must park");
    assert_eq!(count(&ts.store, "ydoc_updates", &key), 1);

    let skipped = maybe_compact(&mut ts.store, &key, 0, &NoFaults, 1_002)
        .expect("forced compaction must inspect parked state");
    assert!(matches!(
        skipped,
        TxnOutcome::Committed(CompactOutcome::Skipped { pending: 1 })
    ));
    assert_eq!(count(&ts.store, "ydoc_updates", &key), 1);
    assert_eq!(count(&ts.store, "ydoc_snapshots", &key), 0);

    apply_remote_update(
        &mut ts.store,
        &key,
        &RemoteUpdate {
            origin_id: "origin-a".to_owned(),
            origin_seq: 1,
            bytes: dependency,
        },
        &NoFaults,
        1_003,
    )
    .expect("dependency arrival must resolve the parked update");
    assert_eq!(count(&ts.store, "ydoc_updates", &key), 2);
    let resolved = load_persisted(&ts.store, &key)
        .expect("load")
        .expect("marker");
    assert_eq!(resolved.doc.plaintext_string(), "ab");

    let compacted = maybe_compact(&mut ts.store, &key, 0, &NoFaults, 1_004)
        .expect("resolved lineage may compact");
    assert!(matches!(
        compacted,
        TxnOutcome::Committed(CompactOutcome::Compacted {
            pruned_updates: 2,
            ..
        })
    ));
    let reconstructed = load_persisted(&ts.store, &key)
        .expect("load compacted")
        .expect("marker");
    assert_eq!(reconstructed.doc.plaintext_string(), "ab");
}

#[test]
fn nested_frontmatter_keys_are_sorted_deterministically() {
    // Constraint 2: yjs preserves object insertion order (gamma, alpha, beta,
    // delta); yrs re-encodes nested Any::Map in HashMap order. The canonical
    // content and the projection MUST sort nested keys, so the durable content
    // equals the yjs frontmatter (order-independent) AND the projection lists
    // nested keys in SORTED order.
    let fx = load_fixture("nestedFrontmatter");
    let doc = Ydoc::wire();
    for u in &fx.updates {
        doc.apply(&decode_b64(u)).expect("apply");
    }
    // Content equality (order-independent serde Value comparison).
    assert_eq!(doc.frontmatter_json(), fx.expected["frontmatter"]);

    // Projection sorts nested keys: alpha < beta < delta < gamma.
    let markdown = doc.project(ContentKind::Richdoc).markdown;
    let a = markdown.find("alpha").expect("alpha");
    let b = markdown.find("beta").expect("beta");
    let d = markdown.find("delta").expect("delta");
    let g = markdown.find("gamma").expect("gamma");
    assert!(
        a < b && b < d && d < g,
        "nested keys not sorted in projection:\n{markdown}"
    );
}

// ---- inductive content-parity sweep (residual class: hostile re-encode) ----
//
// The reviewer's residual: a peer re-encodes an already-known `(client,
// clock)` with DIFFERENT content — WITHOUT a clock shortfall (the
// candidate-clock-coverage check sees full coverage) and WITHOUT an interior-
// scalar edit boundary named on the wire (the structural boundary pass sees
// nothing). No honest peer ever redefines a clock it has already used, so
// this corpus is adversarial-construction-only: for many base texts (plain
// ASCII, ASCII interleaved with multi-unit emoji, accented Latin), corrupt
// EVERY ASCII byte of the SAME wire update's string payload to a different
// ASCII byte and drive it back through the gate as a "candidate" claiming the
// identical (client, clock) range as the already-integrated base. Each must
// be rejected; none may panic.

/// Locate the string payload of a `plaintext_insert(0, text)` delta: the
/// fixed `plainText` root-name marker, a 1-byte length prefix (valid for the
/// short ASCII/emoji test strings used here, all under 128 UTF-8 bytes), then
/// the payload itself.
fn plaintext_payload_range(update: &[u8]) -> std::ops::Range<usize> {
    let marker = b"plainText";
    let marker_at = update
        .windows(marker.len())
        .position(|w| w == marker)
        .expect("plainText root marker present");
    let len_at = marker_at + marker.len();
    let payload_len = update[len_at] as usize;
    let start = len_at + 1;
    start..start + payload_len
}

#[test]
fn replay_parity_rejects_content_redefinition_sweep() {
    let bases = [
        "hello",
        "a\u{1F600}b",          // ascii + one 2-unit emoji + ascii
        "x\u{1F600}\u{1F601}y", // ascii + two 2-unit emoji + ascii
        "cafe over there",
        "\u{1F600}mid\u{1F601}",
    ];
    let mut cases = 0usize;
    for text in bases {
        let producer = Ydoc::wire();
        let base_update = producer.plaintext_insert(0, text);
        let payload = plaintext_payload_range(&base_update);

        let seeded = Ydoc::wire();
        seeded.apply(&base_update).expect("seed base");

        for i in payload.clone() {
            let original = base_update[i];
            if !original.is_ascii() {
                continue; // only flip whole ASCII bytes — keeps the patched
                          // payload valid UTF-8 without reshaping multi-byte
                          // sequences elsewhere in the string.
            }
            let replacement = if original == b'z' { b'y' } else { b'z' };
            let mut hostile = base_update.clone();
            hostile[i] = replacement;
            assert!(
                std::str::from_utf8(&hostile[payload.clone()]).is_ok(),
                "patch must stay valid UTF-8: text={text:?} offset={i}"
            );

            let error = validate_replay_parity_for_test(&seeded, &hostile).expect_err(&format!(
                "content redefinition must be rejected: text={text:?} offset={i}"
            ));
            assert!(
                matches!(error, CollabError::ReplayParityViolation { .. }),
                "text={text:?} offset={i}: {error:?}"
            );
            cases += 1;
        }
    }
    assert!(cases >= 20, "expected a broad hostile sweep, got {cases}");
    eprintln!("content-parity sweep: {cases} hostile redefinitions rejected, 0 panics");
}

/// The gate is not re-exported at the crate root (it is reached through the
/// durable append paths); drive it the same way `append_local_update` does —
/// through a store, so the exact production call path is exercised.
fn validate_replay_parity_for_test(seeded: &Ydoc, hostile: &[u8]) -> Result<(), CollabError> {
    let mut ts = fresh_store("content-parity-sweep");
    let key = test_key();
    seed_parents(&mut ts.store, &key, 1_000);
    dohc_engine_collab::ensure_marker(
        &mut ts.store,
        &key,
        ContentKind::Plaintext,
        Regime::LocalOnly,
        &NoFaults,
        1_000,
    )
    .expect("marker");
    record_local_update(
        &mut ts.store,
        &key,
        &seeded.encode_full_state(),
        &NoFaults,
        1_001,
    )
    .expect("seed base into store");
    record_local_update(&mut ts.store, &key, hostile, &NoFaults, 1_002).map(|_| ())
}
